import{_ as i,a0 as p,w as o,s as r,ao as d,I as s,x as e,a1 as l,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"R 語言繪製數據：圖表篇 | LCTT x X-CMD","titleTemplate":false,"description":"R 語言繪製數據：圖表篇 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"R 語言繪製數據：圖表篇 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"R 語言繪製數據：圖表篇 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220527 Plotting Data in R- Graphs","title":"R 語言繪製數據：圖表篇","tag":"202207","desc":""},"relativePath":"202207/20220527 Plotting Data in R- Graphs.md","filePath":"[post].md"}'),c={name:"202207/20220527 Plotting Data in R- Graphs.md"};function g(u,t,h,y,f,x){const a=p("Link");return o(),r("div",null,[t[31]||(t[31]=d(`<h1 id="r-語言繪製數據-圖表篇" tabindex="-1">R 語言繪製數據：圖表篇 <a class="header-anchor" href="#r-語言繪製數據-圖表篇" aria-label="Permalink to “R 語言繪製數據：圖表篇”">​</a></h1><p>R 語言有非常多的繪圖和數據可視化的包，比如 <code>graphics</code>、<code>lattice</code>、<code>ggplot2</code> 等。這是 R 語言系列的第 9 篇文章，我們會介紹 R 中用來繪圖的各種函數。</p><p><img src="https://img.linux.net.cn/data/attachment/album/202207/15/155129rsfee22secwyii8w.jpg" alt=""></p><p>本文使用的 R 是 4.1.2 版本，運行環境為 Parabola GNU/Linux-libre (x86-64)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ R --version</span></span>
<span class="line"><span></span></span>
<span class="line"><span>R version 4.1.2 (2021-11-01) -- &quot;Bird Hippie&quot;</span></span>
<span class="line"><span>Copyright (C) 2021 The R Foundation for Statistical Computing</span></span>
<span class="line"><span>Platform: x86_64-pc-linux-gnu (64-bit)</span></span></code></pre></div>`,5)),s("p",null,[t[1]||(t[1]=e("R 是自由軟件，沒有任何擔保責任。只要遵守 GNU 通用公共許可證的版本 2 或者版本 3，你就可以對它進行（修改和）再分發。詳情見 ",-1)),l(a,{href:"https://www.gnu.org/licenses/"},{default:n(()=>[...t[0]||(t[0]=[e("https://www.gnu.org/licenses/",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[32]||(t[32]=s("h3",{id:"折線圖",tabindex:"-1"},[e("折線圖 "),s("a",{class:"header-anchor",href:"#折線圖","aria-label":"Permalink to “折線圖”"},"​")],-1)),s("p",null,[t[4]||(t[4]=e("我們以印度全境消費者物價指數（CPI -- 鄉村/城市）數據集為研究對象，它可以從 ",-1)),l(a,{href:"https://data.gov.in/catalog/all-india-consumer-price-index-ruralurban-0"},{default:n(()=>[...t[3]||(t[3]=[e("https://data.gov.in/catalog/all-india-consumer-price-index-ruralurban-0",-1)])]),_:1}),t[5]||(t[5]=e(" 下載。選擇“截止到 2021 年 11 月” 的版本，用 ",-1)),t[6]||(t[6]=s("code",null,"read.csv",-1)),t[7]||(t[7]=e(" 函數讀取下載好的文件，如下所示：",-1))]),t[33]||(t[33]=d(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; cpi &lt;- read.csv(file=&quot;CPI.csv&quot;, sep=&quot;,&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; head(cpi)</span></span>
<span class="line"><span>Sector Year Name Andhra.Pradesh Arunachal.Pradesh Assam Bihar</span></span>
<span class="line"><span>1 Rural 2011 January 104 NA 104 NA</span></span>
<span class="line"><span>2 Urban 2011 January 103 NA 103 NA</span></span>
<span class="line"><span>3 Rural+Urban 2011 January 103 NA 104 NA</span></span>
<span class="line"><span>4 Rural 2011 February 107 NA 105 NA</span></span>
<span class="line"><span>5 Urban 2011 February 106 NA 106 NA</span></span>
<span class="line"><span>6 Rural+Urban 2011 February 105 NA 105 NA</span></span>
<span class="line"><span>Chattisgarh Delhi Goa Gujarat Haryana Himachal.Pradesh Jharkhand Karnataka</span></span>
<span class="line"><span>1 105 NA 103 104 104 104 105 104</span></span>
<span class="line"><span>2 104 NA 103 104 104 103 104 104</span></span>
<span class="line"><span>3 104 NA 103 104 104 103 105 104</span></span>
<span class="line"><span>4 107 NA 105 106 106 105 107 106</span></span>
<span class="line"><span>5 106 NA 105 107 107 105 107 108</span></span>
<span class="line"><span>6 105 NA 104 105 106 104 106 106</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>以 Punjab 州為例，對每年各月份的 CPI 值求和，然後用 <code>plot</code> 函數畫一張折線圖：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; punjab &lt;- aggregate(x=cpi$Punjab, by=list(cpi$Year), FUN=sum)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; head(punjab)</span></span>
<span class="line"><span>Group.1 x</span></span>
<span class="line"><span>1 2011 3881.76</span></span>
<span class="line"><span>2 2012 4183.30</span></span>
<span class="line"><span>3 2013 4368.40</span></span>
<span class="line"><span>4 2014 4455.50</span></span>
<span class="line"><span>5 2015 4584.30</span></span>
<span class="line"><span>6 2016 4715.80</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; plot(punjab$Group.1, punjab$x, type=&quot;l&quot;, main=&quot;Punjab Consumer Price Index upto November 2021&quot;, xlab=&quot;Year&quot;, ylab=&quot;Consumer Price Index&quot;)</span></span></code></pre></div><p><code>plot</code> 函數可以傳入如下參數：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">參數</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>x</code></td><td style="text-align:left;">向量類型，用於繪製 x 軸的數據</td></tr><tr><td style="text-align:left;"><code>y</code></td><td style="text-align:left;">向量或列表類型，用於繪製 y 軸的數據</td></tr><tr><td style="text-align:left;"><code>type</code></td><td style="text-align:left;">設置繪圖類型：<code>p</code> 畫點；<code>l</code> 畫線；<code>o</code> 同時畫點和線，且相互重疊；<code>s</code> 畫階梯線；<code>h</code> 畫鉛垂線</td></tr><tr><td style="text-align:left;"><code>xlim</code></td><td style="text-align:left;">x 軸範圍</td></tr><tr><td style="text-align:left;"><code>ylim</code></td><td style="text-align:left;">y 軸範圍</td></tr><tr><td style="text-align:left;"><code>main</code></td><td style="text-align:left;">標題</td></tr><tr><td style="text-align:left;"><code>sub</code></td><td style="text-align:left;">副標題</td></tr><tr><td style="text-align:left;"><code>xlab</code></td><td style="text-align:left;">x 軸標題</td></tr><tr><td style="text-align:left;"><code>ylab</code></td><td style="text-align:left;">y 軸標題</td></tr><tr><td style="text-align:left;"><code>axes</code></td><td style="text-align:left;">邏輯型，是否繪製座標軸</td></tr></tbody></table></div><p>結果如圖 1。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-1-Line-chart.jpg" alt="Figure 1: Line chart"></p><h3 id="自相關圖" tabindex="-1">自相關圖 <a class="header-anchor" href="#自相關圖" aria-label="Permalink to “自相關圖”">​</a></h3><p>自相關圖能在時序分析中展示一個變量是否具有自相關性，可以用 R 中的 <code>acf</code> 函數繪製。<code>acf</code> 函數可以設置三種自相關類型：<code>correlation</code>、<code>covariance</code> 或 <code>partial</code>。圖 2 是 Punjab 州 CPI 值的自相關圖，x 表示 CPI。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>acf(punjab$x,main=&#39;x&#39;)</span></span></code></pre></div><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-2-ACF-chart.jpg" alt="Figure 2: ACF chart"></p><p><code>acf</code> 函數可以傳入以下參數：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">參數</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>x</code></td><td style="text-align:left;">一個單變量或多變量的時序對象，或者一個數值向量或數值矩陣</td></tr><tr><td style="text-align:left;"><code>lag.max</code></td><td style="text-align:left;">最大滯後階數</td></tr><tr><td style="text-align:left;"><code>type</code></td><td style="text-align:left;">字符型，設置所計算的自相關類型：<code>correlation</code>、<code>covariance</code> 或 <code>partial</code></td></tr><tr><td style="text-align:left;"><code>plot</code></td><td style="text-align:left;">邏輯性，若 <code>TRUE</code> 則繪製圖像，若 <code>FALSE</code> 則打印傳入數據的描述信息</td></tr><tr><td style="text-align:left;"><code>i</code></td><td style="text-align:left;">一組要保留的時差滯後</td></tr><tr><td style="text-align:left;"><code>j</code></td><td style="text-align:left;">一組要保留的名稱或數字</td></tr></tbody></table></div><h3 id="柱狀圖" tabindex="-1">柱狀圖 <a class="header-anchor" href="#柱狀圖" aria-label="Permalink to “柱狀圖”">​</a></h3><p>R 中畫柱狀圖的函數是 <code>barplot</code>。下面的代碼用來畫 Punjab 州 CPI 的柱狀圖，如圖3：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; barplot(punjab$x, main=&quot;Punjab Consumer Price Index&quot;, sub=&quot;Upto November 2021&quot;, xlab=&quot;Year&quot;, ylab=&quot;Consumer Price Index&quot;, col=&quot;navy&quot;)</span></span></code></pre></div><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-3-Line-chart-of-Punjabs-CPI.jpg" alt="Figure 3: Line chart of Punjab&#39;s CPI"></p><p><code>barplot</code> 函數的使用方法非常靈活，可以傳入以下參數：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">參數</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>height</code></td><td style="text-align:left;">數值向量或數值矩陣，包含用於繪圖的數據</td></tr><tr><td style="text-align:left;"><code>width</code></td><td style="text-align:left;">數值向量，用於設置柱寬</td></tr><tr><td style="text-align:left;"><code>space</code></td><td style="text-align:left;">柱間距</td></tr><tr><td style="text-align:left;"><code>beside</code></td><td style="text-align:left;">邏輯型，若 <code>FALSE</code> 則繪製堆積柱狀圖，若 <code>TRUE</code> 則繪製並列柱狀圖</td></tr><tr><td style="text-align:left;"><code>density</code></td><td style="text-align:left;">數值型，設置陰影線的填充密度（條數/英寸），默認為 <code>NULL</code>，即不填充陰影線</td></tr><tr><td style="text-align:left;"><code>angle</code></td><td style="text-align:left;">數值型，填充線條的角度，默認為 45</td></tr><tr><td style="text-align:left;"><code>border</code></td><td style="text-align:left;">柱形邊緣的顏色</td></tr><tr><td style="text-align:left;"><code>main</code></td><td style="text-align:left;">標題</td></tr><tr><td style="text-align:left;"><code>sub</code></td><td style="text-align:left;">副標題</td></tr><tr><td style="text-align:left;"><code>xlab</code></td><td style="text-align:left;">x 軸標題</td></tr><tr><td style="text-align:left;"><code>ylab</code></td><td style="text-align:left;">y 軸標題</td></tr><tr><td style="text-align:left;"><code>xlim</code></td><td style="text-align:left;">x 軸範圍</td></tr><tr><td style="text-align:left;"><code>ylim</code></td><td style="text-align:left;">y 軸範圍</td></tr><tr><td style="text-align:left;"><code>axes</code></td><td style="text-align:left;">邏輯型，是否繪製座標軸</td></tr></tbody></table></div><p>用 <code>help</code> 命令可以查看 <code>barplot</code> 函數的詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; help(barplot)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>barplot                package:graphics                R Documentation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bar Plots</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Description:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>     Creates a bar plot with vertical or horizontal bars.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>     barplot(height, ...)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>     ## Default S3 method:</span></span>
<span class="line"><span>     barplot(height, width = 1, space = NULL,</span></span>
<span class="line"><span>             names.arg = NULL, legend.text = NULL, beside = FALSE,</span></span>
<span class="line"><span>             horiz = FALSE, density = NULL, angle = 45,</span></span>
<span class="line"><span>             col = NULL, border = par(&quot;fg&quot;),</span></span>
<span class="line"><span>             main = NULL, sub = NULL, xlab = NULL, ylab = NULL,</span></span>
<span class="line"><span>             xlim = NULL, ylim = NULL, xpd = TRUE, log = &quot;&quot;,</span></span>
<span class="line"><span>             axes = TRUE, axisnames = TRUE,</span></span>
<span class="line"><span>             cex.axis = par(&quot;cex.axis&quot;), cex.names = par(&quot;cex.axis&quot;),</span></span>
<span class="line"><span>             inside = TRUE, plot = TRUE, axis.lty = 0, offset = 0,</span></span>
<span class="line"><span>             add = FALSE, ann = !add &amp;&amp; par(&quot;ann&quot;), args.legend = NULL, ...)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>     ## S3 method for class &#39;formula&#39;</span></span>
<span class="line"><span>     barplot(formula, data, subset, na.action,</span></span>
<span class="line"><span>             horiz = FALSE, xlab = NULL, ylab = NULL, ...)</span></span></code></pre></div><h3 id="餅圖" tabindex="-1">餅圖 <a class="header-anchor" href="#餅圖" aria-label="Permalink to “餅圖”">​</a></h3>`,22)),s("p",null,[t[9]||(t[9]=e("繪製餅圖時要多加註意，因為餅圖不一定能展示出各扇形間的區別。（LCTT 譯註：根據統計學家和一些心理學家的調查結果，這種以比例展示數據的統計圖形 ",-1)),l(a,{href:"https://bookdown.org/xiangyun/msg/gallery.html#sec:pie"},{default:n(()=>[...t[8]||(t[8]=[e("實際上是很糟糕的可視化方式",-1)])]),_:1}),t[10]||(t[10]=e("，因此，R 關於餅圖的幫助文件中清楚地説明了並不推薦使用餅圖，而是使用條形圖或點圖作為替代。） 用 ",-1)),t[11]||(t[11]=s("code",null,"subset",-1)),t[12]||(t[12]=e(" 函數獲得 Gujarat 州在 2021 年 1 月 Rural、Urban、Rurual+Urban 的 CPI 值：",-1))]),t[34]||(t[34]=d(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; jan2021 &lt;- subset(cpi, Name==&quot;January&quot; &amp; Year==&quot;2021&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; jan2021$Gujarat</span></span>
<span class="line"><span>[1] 153.9 151.2 149.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; names &lt;- c(&#39;Rural&#39;, &#39;Urban&#39;, &#39;Rural+Urban&#39;)</span></span></code></pre></div><p>使用 <code>pie</code> 函數為 Gujarat 州的 CPI 值生成餅圖，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; pie(jan2021$Gujarat, names, main=&quot;Gujarat CPI Rural and Urban Pie Chart&quot;)</span></span></code></pre></div><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-4-Pie-chart.jpg" alt="Figure 4: Pie chart"></p><p><code>pie</code> 函數可以傳入以下參數：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">參數</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;">\`x</td><td style="text-align:left;">元素大於 0 的數值向量</td></tr><tr><td style="text-align:left;"><code>label</code></td><td style="text-align:left;">字符向量，用於設置每個扇形的標籤</td></tr><tr><td style="text-align:left;"><code>radius</code></td><td style="text-align:left;">餅圖的半徑</td></tr><tr><td style="text-align:left;"><code>clockwise</code></td><td style="text-align:left;">邏輯型，若 <code>TRUE</code> 則順時針繪圖，若 <code>FALSE</code> 則逆時針繪圖</td></tr><tr><td style="text-align:left;"><code>density</code></td><td style="text-align:left;">數值型，設置陰影線的填充密度（條數/英寸），默認為 <code>NULL</code>，即不填充陰影線</td></tr><tr><td style="text-align:left;"><code>angle</code></td><td style="text-align:left;">數值型，填充線條的角度，默認為 45</td></tr><tr><td style="text-align:left;"><code>col</code></td><td style="text-align:left;">數值向量，用於設置顏色</td></tr><tr><td style="text-align:left;"><code>lty</code></td><td style="text-align:left;">每個扇形的線條類型</td></tr><tr><td style="text-align:left;"><code>main</code></td><td style="text-align:left;">標題</td></tr></tbody></table></div><h3 id="箱線圖" tabindex="-1">箱線圖 <a class="header-anchor" href="#箱線圖" aria-label="Permalink to “箱線圖”">​</a></h3>`,7)),s("p",null,[t[14]||(t[14]=e("（LCTT 譯註：箱線圖主要是 ",-1)),l(a,{href:"https://bookdown.org/xiangyun/msg/gallery.html#sec:boxplot"},{default:n(()=>[...t[13]||(t[13]=[e("從四分位數的角度出發",-1)])]),_:1}),t[15]||(t[15]=e(" 描述數據的分佈，它通過最大值（Q4）、上四分位數（Q3）、中位數（Q2）、下四分位數（Q1） 和最小值（Q0）五處位置來獲取一維數據的分佈概況。我們知道，這五處位置之間依次包含了四段數據，每段中數據量均為總數據量的 1/4。通過每一段數據佔據的長度，我們可以大致推斷出數據的集中或離散趨勢。長度越短，説明數據在該區間上越密集，反之則稀疏。）",-1))]),t[35]||(t[35]=d(`<p>箱線圖能夠用“<ruby>須線<rt>whisker</rt></ruby>” 展示一個變量的<ruby>四分位距<rt>Interquartile Range</rt></ruby>（簡稱 IQR=Q3-Q1）。用上下四分位數分別加/減內四分位距，再乘以一個人為設定的倍數 <code>range</code>（見下面的參數列表），得到 <code>range * c(Q1-IQR, Q3+IQR)</code>，超過這個範圍的數據點就被視作離羣點，在圖中直接以點的形式表示出來。</p><p><code>boxplot</code> 函數可以傳入以下參數：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">參數</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>data</code></td><td style="text-align:left;">數據框或列表，用於參數類型為公式的情況</td></tr><tr><td style="text-align:left;"><code>x</code></td><td style="text-align:left;">數值向量或者列表，若為列表則對列表中每一個子對象依次作出箱線圖</td></tr><tr><td style="text-align:left;"><code>width</code></td><td style="text-align:left;">設置箱子的寬度</td></tr><tr><td style="text-align:left;"><code>outline</code></td><td style="text-align:left;">邏輯型，設置是否繪製離羣點</td></tr><tr><td style="text-align:left;"><code>names</code></td><td style="text-align:left;">設置每個箱子的標籤</td></tr><tr><td style="text-align:left;"><code>border</code></td><td style="text-align:left;">設置每個箱子的邊緣的顏色</td></tr><tr><td style="text-align:left;"><code>range</code></td><td style="text-align:left;">延伸倍數，設置箱線圖末端（須）延伸到什麼位置</td></tr><tr><td style="text-align:left;"><code>plot</code></td><td style="text-align:left;">邏輯型，設置是否生成圖像，若 TRUE 則生成圖像，若 FALSE 則打印傳入數據的描述信息</td></tr><tr><td style="text-align:left;"><code>horizontal</code></td><td style="text-align:left;">邏輯型，設置箱線圖是否水平放置</td></tr></tbody></table></div><p>用 <code>boxplot</code> 函數繪製部分州的箱線圖：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; names &lt;- c (&#39;Andaman and Nicobar&#39;, &#39;Lakshadweep&#39;, &#39;Delhi&#39;, &#39;Goa&#39;, &#39;Gujarat&#39;, &#39;Bihar&#39;)</span></span>
<span class="line"><span>&gt; boxplot(cpi$Andaman.and.Nicobar, cpi$Lakshadweep, cpi$Delhi, cpi$Goa, cpi$Gujarat, cpi$Bihar, names=names)</span></span></code></pre></div><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-5-ox-plot.jpg" alt="Figure 5: Box plot"></p><h3 id="qq-圖" tabindex="-1">QQ 圖 <a class="header-anchor" href="#qq-圖" aria-label="Permalink to “QQ 圖”">​</a></h3><p><ruby>QQ 圖<rt>Quantile-Quantile plot</rt></ruby>可以用來對比兩個數據集，也可以用來檢查數據是否服從某種理論分佈。<code>qqnorm</code> 函數能繪製正態分佈 QQ 圖，可以檢驗數據是否服從正態分佈，用下面的代碼繪製 Punjab 州 CPI 數據的 QQ 圖：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; qqnorm(punjab$x)</span></span></code></pre></div><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-6-Q-Q-plot.jpg" alt="Figure 6: Q-Q plot"></p><p><code>qqline</code> 函數可以向正態分佈 QQ 圖上添加理論分佈曲線，它可以傳入以下參數：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">參數</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>x</code></td><td style="text-align:left;">第一個數據樣本</td></tr><tr><td style="text-align:left;"><code>y</code></td><td style="text-align:left;">第二個數據樣本</td></tr><tr><td style="text-align:left;"><code>datax</code></td><td style="text-align:left;">邏輯型，設置是否以 x 軸表示理論曲線的值，默認為 <code>FALSE</code></td></tr><tr><td style="text-align:left;"><code>probs</code></td><td style="text-align:left;">長度為 2 的數值向量，代表概率</td></tr><tr><td style="text-align:left;"><code>xlab</code></td><td style="text-align:left;">x 軸標題</td></tr><tr><td style="text-align:left;"><code>ylab</code></td><td style="text-align:left;">y 軸標題</td></tr><tr><td style="text-align:left;"><code>qtype</code></td><td style="text-align:left;"><code>[1,9]</code> 內的整數，設置分位計算類型，詳情見 <code>help(quantile)</code> 的類型小節</td></tr></tbody></table></div><h3 id="等高圖" tabindex="-1">等高圖 <a class="header-anchor" href="#等高圖" aria-label="Permalink to “等高圖”">​</a></h3><p>等高圖可以描述三維數據，在 R 中對應的函數是 <code>contour</code>，這個函數也可以用來向已有的圖表添加等高線。等高圖常與其他圖表一起使用。我們用 <code>contour</code> 對 R 中的 <code>volcano</code> 數據集（奧克蘭的火山地形信息）繪製等高圖，代碼如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; contour(volcano)</span></span></code></pre></div><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-7-Volcano.jpg" alt="Figure 7: Volcano"></p><p><code>contour</code> 函數的常用參數如下：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">參數</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>x,y</code></td><td style="text-align:left;">z 中數值對應的點在平面上的位置</td></tr><tr><td style="text-align:left;"><code>z</code></td><td style="text-align:left;">數值向量</td></tr><tr><td style="text-align:left;"><code>nlevels</code></td><td style="text-align:left;">設置等高線的條數，調整等高線的疏密</td></tr><tr><td style="text-align:left;"><code>labels</code></td><td style="text-align:left;">等高線上的標記字符串，默認是高度的數值</td></tr><tr><td style="text-align:left;"><code>xlim</code></td><td style="text-align:left;">設置 x 軸的範圍</td></tr><tr><td style="text-align:left;"><code>ylim</code></td><td style="text-align:left;">設置 y 軸的範圍</td></tr><tr><td style="text-align:left;"><code>zlim</code></td><td style="text-align:left;">設置 z 軸的範圍</td></tr><tr><td style="text-align:left;"><code>axes</code></td><td style="text-align:left;">設置是否繪製座標軸</td></tr><tr><td style="text-align:left;"><code>col</code></td><td style="text-align:left;">設置等高線的顏色</td></tr><tr><td style="text-align:left;"><code>lty</code></td><td style="text-align:left;">設置線條的類型</td></tr><tr><td style="text-align:left;"><code>lwd</code></td><td style="text-align:left;">設置線條的粗細</td></tr><tr><td style="text-align:left;"><code>vfont</code></td><td style="text-align:left;">設置標籤字體</td></tr></tbody></table></div><p>等高線之間的區域可以用顏色填充，每種顏色表示一個高度範圍，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; filled.contour(volcano, asp = 1)</span></span>
<span class="line"><span># asp 為圖形縱橫比，即 y 軸上的 1 單位長度和 x 軸上 1 單位長度的比率</span></span></code></pre></div><p>填充結果見圖 8。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-8-Filled-volcano.jpg" alt="Figure 8: Filled volcano"></p><p>掌握上述內容後，你可以嘗試 R 語言 <code>graphics</code> 包中的其他函數和圖表（LCTT 譯註：用 <code>help(package=graphics)</code> 可以查看 graphics 包提供的函數列表）。</p><hr>`,24)),s("p",null,[t[17]||(t[17]=e("via: ",-1)),l(a,{href:"https://www.opensourceforu.com/2022/05/plotting-data-in-r-graphs/"},{default:n(()=>[...t[16]||(t[16]=[e("https://www.opensourceforu.com/2022/05/plotting-data-in-r-graphs/",-1)])]),_:1})]),s("p",null,[t[22]||(t[22]=e("作者：",-1)),l(a,{href:"https://www.opensourceforu.com/author/shakthi-kannan/"},{default:n(()=>[...t[18]||(t[18]=[e("Shakthi Kannan",-1)])]),_:1}),t[23]||(t[23]=e(" 選題：",-1)),l(a,{href:"https://github.com/lkxed"},{default:n(()=>[...t[19]||(t[19]=[e("lkxed",-1)])]),_:1}),t[24]||(t[24]=e(" 譯者：",-1)),l(a,{href:"https://github.com/tanloong"},{default:n(()=>[...t[20]||(t[20]=[e("tanloong",-1)])]),_:1}),t[25]||(t[25]=e(" 校對：",-1)),l(a,{href:"https://github.com/wxy"},{default:n(()=>[...t[21]||(t[21]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[28]||(t[28]=e("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[26]||(t[26]=[e("LCTT",-1)])]),_:1}),t[29]||(t[29]=e(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:n(()=>[...t[27]||(t[27]=[e("Linux中國",-1)])]),_:1}),t[30]||(t[30]=e(" 榮譽推出",-1))])])}const C=i(c,[["render",g]]);export{m as __pageData,C as default};
